d age|1973|10|25|1932|8|7}}"},"death_place":{"wt":"[[Addis Ababa]], Ethiopia"},"resting_place":{"wt":"Saint Joseph Church, Addis&amp;nbsp;Ababa"},"resting_place_coordinates":{"wt":"{{nowrap|{{Coord|8|58|9.7|N|38|45|53.6|E}}}}"},"height":{"wt":"177 cm&lt;ref name=sr>{{cite Sports-Reference |url=https://www.sports-reference.com/olympics/athletes/bi/abebe-bikila-1.html |title=Abebe Bikila |archive-url=https://web.archive.org/web/20200417173649/https://www.sports-reference.com/olympics/athletes/bi/abebe-bikila-1.html |archive-date=April 17, 2020}}&lt;/ref>"},"weight":{"wt":"57 kg&lt;ref name=sr/>"},"sport":{"wt":"[[Long-distance running]]"},"event":{"wt":"[[Marathon]], 10,000 m"},"personal_best":{"wt":"{{ubl|Marathon – 2:12:11.2 (Tokyo 1964)|10,000 m – 29:00.8 (Berlin 1962)&lt;ref name=tf>{{cite web |url=http://trackfield.brinkster.net/Profile.asp?ID=565&amp;Gender=M |title=Abebe Bikila |website=trackfield.brinkster.net |access-date=October 10, 2019}}&lt;/ref>}}"},"medal_templates":{"wt":"{{Medal|Country|{{Flagu|Ethiopia|1897}}}} 
