iversity":{"wt":""},"relatives":{"wt":"[[Tatjana Smith]] (aunt of his children, former sister-in-law)."},"position":{"wt":"[[Flanker (rugby union)|Loose forward]]"},"currentclub":{"wt":"{{Rut|Stormers}}"},"youthyears1":{"wt":"2007–2009"},"youthclubs1":{"wt":"{{Rut|Eastern Province Kings}}"},"youthyears2":{"wt":"2010–2012"},"youthclubs2":{"wt":"{{Rut|Western Province}}"},"years1":{"wt":"2011–2021"},"clubs1":{"wt":"{{Rut|Western Province}}"},"apps1":{"wt":"34"},"points1":{"wt":"35"},"years2":{"wt":"2012–2020"},"clubs2":{"wt":"{{Rut|Stormers}}"},"apps2":{"wt":"118"},"points2":{"wt":"95"},"years3":{"wt":"2021–2023"},"clubs3":{"wt":"{{Rut|Sharks}}"},"apps3":{"wt":"31"},"points3":{"wt":"20"},"years4":{"wt":"2023–2024"},"clubs4":{"wt":"[[Racing 92]]"},"apps4":{"wt":"18"},"points4":{"wt":"5"},"years5":{"wt":"2024–2026"},"clubs5":{"wt":"{{Rut|Sharks}}"},"apps5":{"wt":"18"},"points5":{"wt":"55"},"years6":{"wt":"2026–"},"clubs6":{"wt":"{{Rut|Stormers}}"},"apps6":{"wt":""},"points6":{"wt":""},"repyears1":{"wt":"2010–2011"},"repteam1":{"wt":"[[South Africa national under-20 rugby union team|South Africa U20]]"},"repcaps1":{"wt":"8"},"reppoints1":{"wt":"10"},"repyears2":{"wt":"2013–"},"repteam2":{"wt":"{{nrut|South Africa}}"},"repcaps2":{"wt":"100"},"reppoints2":{"wt":"70"},"clubupdate":{"wt":"25 July 2026"},"repupdate":{"wt":"7 November 2025"},"medals":{"wt":"{{MedalSport|Men&apos;s [[Rugby union|Rugby 15&apos;s]]}}
