emierleague.com/players/886/Lucas-Radebe/overview |access-date=7 November 2019 |publisher=Premier League}}&lt;/ref>"},"position":{"wt":"[[Centre-back]]&lt;ref name=Hugman/>"},"current_club":{"wt":""},"youth_years1":{"wt":""},"youth_clubs1":{"wt":"Diepkloof Wolf Wanderers"},"youth_years2":{"wt":"1987–1988"},"youth_clubs2":{"wt":"ICL Birds"},"youth_years3":{"wt":"1989"},"youth_clubs3":{"wt":"[[Kaizer Chiefs F.C.|Kaizer Chiefs Juniors]]"},"years1":{"wt":"1989–1994"},"clubs1":{"wt":"[[Kaizer Chiefs]]"},"caps1":{"wt":"113+"},"goals1":{"wt":"5+"},"years2":{"wt":"1994–2005"},"clubs2":{"wt":"[[Leeds United F.C.|Leeds United]]"},"caps2":{"wt":"201"},"goals2":{"wt":"0"},"total_caps":{"wt":"314+"},"total_goals":{"wt":"5+"},"national_years1":{"wt":"1992–2003"},"national_team1":{"wt":"[[South Africa national soccer team|South Africa]]"},"national_caps1":{"wt":"70"},"national_goals1":{"wt":"2"},"medal_templates":{"wt":"{{MedalCountry|{{fb|RSA}}}}
